/**
 * Look up the enriched paragraph for a state slug.
 * Returns `null` if no enrichment cell yet (= location page goes noindex).
 */
export function getStateEnrichment(slug: string): string | null {
  return STATE_ENRICHMENT[slug] ?? null;
}

export const STATE_ENRICHMENT_COUNT = Object.keys(STATE_ENRICHMENT).length;
